catalog_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    g_form.setValue('requ', g_user.userID);
	var userSysID = g_user.userID;
	var grUser = new GlideRecord('sys_user');
	if(grUser.get(userSysID)){
		var managerSysID = grUser.manager;
		g_form.setValue('manager',managerSysID)
	}
}
